// Metadata only. READY is permission to prepare checked inputs, never a native
// receipt or proof that a proposed source contact is rooted in a live world.
export const HOST_INPUT_LIMITS=Object.freeze({regionalParts:2,descriptors:320,cellsPerPart:4096,shapes:192,triangles:65536,fallbackShapes:24,fallbackTriangles:8192});
const sha=s=>typeof s==='string'&&/^[a-f0-9]{64}$/.test(s),vector=p=>Array.isArray(p)&&p.length===3&&p.every(Number.isFinite);
export function freezeInput(value){if(value&&typeof value==='object'&&!Object.isFrozen(value)){for(const v of Object.values(value))freezeInput(v);Object.freeze(value);}return value;}
export function qualifyInputOwner(place,id){if(typeof id!=='string'||!id)throw Error('Owner identity required');if(id.includes('::')){if(!id.startsWith(place+'::')||id.split('::').length!==2)throw Error('Owner must be qualified exactly once');return id;}return place+'::'+id;}
export class MapInputNotReadyError extends Error{constructor(report){super('Shared map inputs are NOT_READY: '+report.findings.map(f=>f.code).join(', '));this.name='MapInputNotReadyError';this.code='MAP_INPUT_NOT_READY';this.report=report;}}
export const sameInput=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const same=sameInput,refKey=r=>r&&[r.commit,r.path,r.sha256].join('|');
export function inspectSharedMapInputs(descriptor,inventory,{reviewedRefs=[],approvedProjections=[],requiredModes={},proofKinds=['bearing-face-v1','fixed-embed-v1','fixed-assembly-mount-v1']}={}){
  const p=structuredClone(descriptor||{}),findings=[],add=(code,id,detail)=>findings.push({code,id,detail}),partById=new Map(inventory.parts.map(v=>[v.id,v])),ownerById=new Map(inventory.owners.map(v=>[v.id,v]));
  const qualify=id=>{try{return qualifyInputOwner(p.placeId,id);}catch{return null;}},list=(object,key)=>{if(object[key]===undefined)object[key]=[];if(!Array.isArray(object[key])){add('MALFORMED_COLLECTION',key,'Expected an array.');object[key]=[];}return object[key];};
  for(const key of ['owners','parts','projections'])list(p,key);
  if(!p.support||typeof p.support!=='object')p.support={};for(const key of ['bonds','anchors','requirements','rootTraces'])list(p.support,key);
  // Malformed/incomplete authoring packets are an admission result, not an
  // exception which could accidentally continue into a default host path.
  if([...p.owners,...p.parts,...p.projections,...p.support.bonds,...p.support.anchors,...p.support.requirements,...p.support.rootTraces].some(v=>!v||typeof v!=='object'))return freezeInput({version:1,status:'NOT_READY',findings:[{code:'MALFORMED_RECORD',id:p.placeId}],plan:p});
  const trusted=new Set(reviewedRefs.map(refKey)),approved=r=>!!r&&sha(r.sha256)&&trusted.has(refKey(r));
  if(p.version!==1||p.placeId!==inventory.placeId||!sha(p.sourceRevision))add('SOURCE_REVISION_OR_PLACE',p.placeId,'Pinned version-1 source metadata is required.');
  if(!same(p.grid,{origin:[0,0,0],pitch:[.5,1.06,.5]}))add('GRID_IDENTITY',p.placeId,'Preserve the existing native grid.');
  const limits={...HOST_INPUT_LIMITS,...p.limits};for(const[k,v]of Object.entries(limits))if(!(k in HOST_INPUT_LIMITS)||!Number.isSafeInteger(v)||v<0||v>HOST_INPUT_LIMITS[k]||k.startsWith('fallback')&&v!==HOST_INPUT_LIMITS[k])add('LIMIT_POLICY',k,'Preserve the combined cache and its fallback reserve; no cap increase.');
  const owners=new Map(),parts=new Map();
  for(const o of p.owners||[]){
    try{o.id=qualifyInputOwner(p.placeId,o.id);}catch(e){add('OWNER_ID',o.id,e.message);continue;}
    if(owners.has(o.id))add('DUPLICATE_OWNER',o.id,'One canonical owner only.');owners.set(o.id,o);
    const existing=ownerById.get(o.id),projection=p.projections.find(v=>qualify(v.owner?.id)===o.id);
    if(!existing&&!projection)add('UNKNOWN_OWNER',o.id,'Owner is absent from this catalogue.');
    const expected=existing||projection?.owner;
    if(expected&&(!Object.is(o.fuelAmount,expected.fuelAmount)||!same(o.finish??null,expected.finish??null)||o.fuelClass!==expected.fuelClass))add('CANONICAL_QUANTITY',o.id,'Full original fuel/profile/finish must match before birth.');
    if(!['whole','regional'].includes(o.mode))add('OWNER_MODE_UNBOUND',o.id,'Select and capture a mode before birth.');
    if(requiredModes[o.id]&&o.mode!==requiredModes[o.id])add('OWNER_MODE_POLICY',o.id,'Mode differs from the captured architect selection.');
    if(!Array.isArray(o.parts)||!o.parts.length)add('OWNER_PARTS_UNBOUND',o.id,'Complete physical part ownership is required.');
    if(expected&&!same([...(Array.isArray(o.parts)?o.parts:[])].sort(),[...expected.parts].sort()))add('TRUNCATED_OWNER',o.id,'A local pilot cannot truncate its canonical owner.');
  }
  const added=new Map();let nextPart=inventory.partCount,nextOwner=inventory.ownerCount;
  for(const projection of p.projections||[]){
    const id=projection.owner?.id;
    if(!approvedProjections.some(a=>same(a,projection)))add('PROJECTION_NOT_APPROVED',id,'Exact approved final projection, including matrix/quantity/IDs/pins, is required.');
    if(projection.canonicalOwnerCount!==1||projection.newAnchor!==false||projection.owner?.finish) add('PROJECTION_OWNERSHIP',id,'One owner/quantity and no new grounding or finish.');
    if(!projection.part||!projection.owner){add('PROJECTION_RECORD_UNBOUND',id,'Owner and part records required.');continue;}
    if(projection.part.globalIndex!==nextPart++||projection.owner.globalIndex!==nextOwner++||partById.has(projection.part.id)||ownerById.has(qualify(id))||added.has(projection.part.id))add('PROJECTION_APPEND_IDENTITY',id,'Append stable new identities without reindexing originals.');
    if(!sha(projection.physical?.sha256)||!sha(projection.render?.sha256)||!sha(projection.mapping?.sha256)||projection.physical?.triangles!==projection.render?.triangles||projection.part.physicalGeometry===projection.part.geometry)add('PROJECTION_MAPPING',id,'Separate pinned final physical and mapped render buffers are required.');
    added.set(projection.part.id,{...projection.part,ownerId:qualify(id),physicalTriangles:projection.physical?.triangles});
  }
  let sourceShapes=0,sourceTriangles=0,temporaryShapes=0,temporaryTriangles=0,regionalParts=0,descriptors=0;
  for(const part of p.parts||[]){
    try{part.ownerId=qualifyInputOwner(p.placeId,part.ownerId);}catch(e){add('PART_OWNER_ID',part.id,e.message);continue;}
    const original=partById.get(part.id)||added.get(part.id),owner=owners.get(part.ownerId);if(parts.has(part.id))add('DUPLICATE_PART',part.id,'One original part only.');parts.set(part.id,part);
    if(!original||!owner||!owner.parts?.includes(part.id))add('PART_OWNERSHIP',part.id,'Exact original or appended part/owner membership is required.');
    else if(part.globalIndex!==original.globalIndex||part.ownerId!==original.ownerId||part.geometry!==original.geometry||part.physicalTriangles!==original.physicalTriangles||!same(part.bounds,original.bounds))add('PART_CATALOGUE_IDENTITY',part.id,'Original ordinal, effective geometry, count and bounds must match.');
    if(!original?.static||part.static!==true)add('STATIC_INPUT_REQUIRED',part.id,'Moving/unknown input is not this static cohort.');
    if(part.sourceRange!==null||original?.sourceRange!=null)add('SOURCE_RANGE_NOT_READY',part.id,'No implicit source-range normalization.');
    if(!['original-v1','approved-projection-v1','effective-overlay-v1'].includes(part.lineage?.kind)||part.lineage?.originalPrimitiveMap!=='identity'||!Array.isArray(part.lineage?.generatedCaps))add('LINEAGE_PLAN_NOT_READY',part.id,'Original/effective primitive and cap lineage must be explicit.');
    if(part.lineage?.kind==='effective-overlay-v1'&&!approved(part.lineage.proofRef))add('OVERLAY_PROOF_NOT_REVIEWED',part.id,'Reviewed subdivision/range mapping is required.');
    const plan=part.surfacePlan;
    if(plan?.kind!=='existing-blueprint-v1'||plan.allocation!=='full-canonical-owner'||!approved(plan.proofRef)||!Number.isSafeInteger(plan.definitions)||plan.definitions<1||!Number.isSafeInteger(plan.triangles)||plan.triangles<1)add('SURFACE_PLAN_UNBOUND',part.id,'Reviewed existing blueprint derivation/allocation is required.');
    if(!vector(part.bounds?.min)||!vector(part.bounds?.max))add('BOUNDS_UNBOUND',part.id,'Finite original bounds required.');
    else{
      const lo=part.bounds.min.map((v,i)=>Math.floor(v/[.5,1.06,.5][i]+1e-7)),hi=part.bounds.max.map((v,i)=>v-part.bounds.min[i]<1e-7?lo[i]:Math.ceil(v/[.5,1.06,.5][i]-1e-7)-1),cells=hi.reduce((n,v,i)=>n*(v-lo[i]+1),1);
      if(owner?.mode==='regional'){
        regionalParts++;temporaryShapes++;temporaryTriangles+=cells*part.physicalTriangles*7;
        if(cells>limits.cellsPerPart)add('REGIONAL_CELL_LIMIT',part.id,{cells,limit:limits.cellsPerPart});
        descriptors+=hi.reduce((n,v,i)=>n*(Math.floor(v/[4,1,4][i])-Math.floor(lo[i]/[4,1,4][i])+1),1);
        sourceShapes+=plan?.definitions||0;sourceTriangles+=plan?.triangles||0;
      }
    }
    sourceShapes+=1+(plan?.definitions||0);sourceTriangles+=part.physicalTriangles+(plan?.triangles||0);
  }
  for(const o of owners.values())for(const id of Array.isArray(o.parts)?o.parts:[])if(!parts.has(id))add('MISSING_CANONICAL_PART',id,'Every owned physical part must have an admitted derivation.');
  if(!owners.size||!parts.size)add('COHORT_UNBOUND',p.placeId,'Explicit bounded owners and parts are required.');
  if(regionalParts>limits.regionalParts)add('REGIONAL_PART_LIMIT',p.placeId,{regionalParts,limit:limits.regionalParts});
  if(descriptors>limits.descriptors)add('DESCRIPTOR_LIMIT',p.placeId,{descriptors,limit:limits.descriptors});
  if(sourceShapes+temporaryShapes+limits.fallbackShapes>limits.shapes||sourceTriangles+temporaryTriangles+limits.fallbackTriangles>limits.triangles)add('COMBINED_CACHE_LIMIT',p.placeId,{sourceShapes,sourceTriangles,temporaryShapes,temporaryTriangles,fallbackShapes:limits.fallbackShapes,fallbackTriangles:limits.fallbackTriangles});
  const support=p.support||{},bonds=new Map(),anchors=new Map();
  for(const b of support.bonds||[]){
    if(bonds.has(b.id))add('DUPLICATE_BOND',b.id,'Preserve unique source relationships.');bonds.set(b.id,b);if(!approved(b.proofRef))add('CONTACT_PROOF_NOT_REVIEWED',b.id,'Source proposals are not approved live bindings.');
    if(!['bearing-face','fixed-embed','fixed-assembly-mount'].includes(b.kind)||!['parent-to-child','symmetric-structural'].includes(b.direction))add('BOND_SEMANTICS_UNBOUND',b.id,'Keep explicit original contact kind/direction.');
    if(!proofKinds.includes(b.proofKind))add('PROOF_KIND_NOT_READY',b.id,b.proofKind);
    for(const side of ['parent','child']){const e=b[side],part=parts.get(e?.partId);if(!part||!vector(e.point)||!Number.isSafeInteger(e.primitive)||e.primitive<0||e.primitive>=part.physicalTriangles||!Number.isSafeInteger(e.component)||e.component<0)add('SOURCE_ENDPOINT_UNBOUND',b.id+'/'+side,'Own original face/component/point is required.');
      if(part?.lineage?.generatedCaps?.includes(e?.primitive))add('GENERATED_CAP_ENDPOINT',b.id+'/'+side,'A cap cannot identify an original surface.');
      if(e?.bindingPlan?.kind!=='source-blueprint-original-face-v1'||!approved(e.bindingPlan.proofRef)||!['surface','solid'].includes(e.bindingPlan.channel)||!(/^(plane|face\/\d+)$/.test(e.bindingPlan.suffix))||!vector(e.bindingPlan.surfacePoint)||!Array.isArray(e.bindingPlan.cell)||e.bindingPlan.cell.length!==3||!e.bindingPlan.cell.every(Number.isSafeInteger))add('BIRTH_DERIVATION_PLAN_UNBOUND',b.id+'/'+side,'Reviewed own source face/projection/cell derivation is required.');
      if(e?.bindingPlan?.nativeRecordId!=null||e?.bindingPlan?.nativeCellId!=null)add('PREMATURE_NATIVE_ID',b.id+'/'+side,'Unborn IDs stay null; only genuine receipts may bind them.');
    }
  }
  for(const a of support.anchors||[]){anchors.set(a.id,a);if(!parts.has(a.partId)||!Number.isFinite(a.elevation)||!approved(a.proofRef))add('ANCHOR_MATERIAL_PROOF_UNBOUND',a.id,'Use reviewed existing original-material evidence, never bounds.');}
  for(const g of support.requirements||[]){
    const lower=g.portIds?.map(id=>bonds.get(id)),upper=bonds.get(g.upperBondId);if(lower?.length!==2||lower.some(v=>!v)||!upper){add('ALL_FIXED_PORTS_UNBOUND',g.id,'Both fixed lowers and directed upper are required.');continue;}
    const fitting=parts.get(lower[0].child?.partId)?.ownerId,excluded=new Set([fitting,parts.get(upper.child?.partId)?.ownerId,...g.excludedDescendantOwners||[]]);
    if(new Set(g.portIds).size!==2||lower.some(b=>b.direction!=='parent-to-child'||parts.get(b.child?.partId)?.ownerId!==fitting)||upper.direction!=='parent-to-child'||parts.get(upper.parent?.partId)?.ownerId!==fitting)add('ALL_DIRECTION_OR_OWNER',g.id,'Keep the original directed fitting dependencies.');
    for(const b of lower){const ownerId=parts.get(b.parent?.partId)?.ownerId,t=(support.rootTraces||[]).find(t=>qualify(t.lowerOwnerId)===ownerId);
      if(!t||t.status!=='reviewed-source-root-trace-v1'||!approved(t.proofRef)||t.complete!==true){add('LOWER_ROOT_NOT_READY',ownerId,'Independent reviewed source trace is missing.');continue;}
      const anchor=anchors.get(t.anchorId);let previous=anchor?.partId;for(const id of t.bondIds||[]){const edge=bonds.get(id);if(!edge||edge.parent?.partId!==previous||excluded.has(parts.get(edge.child?.partId)?.ownerId))add('ROOT_TRACE_INCOMPLETE_OR_DEPENDENT',ownerId,id);previous=edge?.child?.partId;}
      if(!anchor||previous!==b.parent?.partId||excluded.has(parts.get(anchor.partId)?.ownerId))add('ROOT_TRACE_INCOMPLETE_OR_DEPENDENT',ownerId,'Trace must end at this lower parent without fitting/upper/descendants.');
    }
  }
  if(!(support.requirements||[]).length)add('ALL_ASSEMBLY_UNBOUND',p.placeId,'This cohort needs its explicit fitting assembly.');
  const unique=[...new Map(findings.map(f=>[[f.code,f.id].join('|'),f])).values()];
  return freezeInput({version:1,status:unique.length?'NOT_READY':'READY',sourceRevision:p.sourceRevision,findings:unique,limits,estimate:{regionalParts,descriptors,sourceShapes,sourceTriangles,temporaryShapes,temporaryTriangles},lateNativeAuthority:'Genuine compiler receipts only; unborn IDs remain null.',pendingAdditions:p.pendingAdditions||[],context:p.context||{},plan:p});
}

import {inspectSharedMapInputs,MapInputNotReadyError,qualifyInputOwner,freezeInput,sameInput} from './shared-map-admission.js';
import {createRegionalSourcePilot} from '../simulation/regional-source-pilot.js';
import {createOriginalSupportPorts,originalMaterialComponents} from '../simulation/original-support-ports.js';
import {bounds,clipTriangle,triangleArea,segmentTriangle,EPS} from '../../workbenches/furnished-house/geometry.js';

// This inventory reads identities/counts, never transforms source positions.
export function sharedMapInputInventory(model){
  return {placeId:model.placeId,partCount:model.parts.length,ownerCount:model.carriers.length,
    owners:model.carriers.map((o,i)=>({id:o.id,globalIndex:i,parts:o.parts.map(n=>model.parts[n]).filter(p=>p.physical).map(p=>p.id),fuelAmount:o.fuelAmount,fuelClass:o.fuelClass,finish:o.finish??null})),
    parts:model.parts.filter(p=>p.physical).map(p=>{const g=model.library.geometries[p.physicalGeometry||p.geometry];return {id:p.id,ownerId:p.carrierId,globalIndex:model.parts.indexOf(p),geometry:p.geometry,physicalTriangles:(g.index?.array.length??g.attributes.position.array.length/3)/3,bounds:p.bounds,static:!p.portalId&&!p.openMatrix,sourceRange:p.originalRange??null};})};
}

export async function loadMapInputJSON(resource,signal){
  const url=new URL('../../'+resource.path,import.meta.url);signal?.throwIfAborted();const response=await fetch(url,{signal});if(!response.ok)throw Error('Map input HTTP '+response.status);
  const bytes=new Uint8Array(await response.arrayBuffer()),digest=await crypto.subtle.digest('SHA-256',bytes),hash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');
  if(hash!==resource.sha256)throw Error('Map input pin mismatch: '+resource.path);signal?.throwIfAborted();return JSON.parse(new TextDecoder().decode(bytes));
}

function checkProjection(projection,physical,render,mapping){
  for(const [raw,expected]of [[physical,projection.physical],[render,projection.render]]){
    const a=raw?.attributes?.position;if(a?.type!=='Float32Array'||a.itemSize!==3||a.array.length!==expected.vertices*3||a.array.some(n=>!Number.isFinite(n)||Math.fround(n)!==n)||(raw.index?.array.length??a.array.length/3)!==expected.triangles*3)throw Error('Final Float32 projection identity/count changed');
  }
  const physicalIndices=physical.index?.array??Array.from({length:projection.physical.vertices},(_,i)=>i),renderIndices=render.index?.array??Array.from({length:projection.render.vertices},(_,i)=>i),map=mapping.renderToPhysicalVertex;
  if(!Array.isArray(map)||map.length!==projection.render.vertices||renderIndices.length!==physicalIndices.length)throw Error('Projection mapping incomplete');
  for(let i=0;i<renderIndices.length;i++){
    const r=renderIndices[i],p=physicalIndices[i];if(!Number.isSafeInteger(r)||r<0||r>=projection.render.vertices||!Number.isSafeInteger(p)||p<0||p>=projection.physical.vertices||map[r]!==p)throw Error('Projection primitive/vertex lineage changed');
    for(let k=0;k<3;k++)if(!Object.is(render.attributes.position.array[r*3+k],physical.attributes.position.array[p*3+k]))throw Error('Render vertex differs from final physical Float32 buffer');
  }
}

// Factory is explicit and reusable. No destination/menu calls it by default.
// Its single owned session is attached AFTER the host decode/source owner.
export function createSharedMapInputFactory({descriptor,policy,loadProjection=loadMapInputJSON}){
  const captured=freezeInput(structuredClone(descriptor));
  return ({model,sources,signal})=>{
    const report=inspectSharedMapInputs(captured,sharedMapInputInventory(model),policy);let prepared=false,closed=false,binding=null,preparing=null,binds=0,lastProducer=null;
    const live=()=>{if(closed)throw Error('Map input session disposed');signal?.throwIfAborted();};
    const ready=()=>{live();if(report.status!=='READY')throw new MapInputNotReadyError(report);};
    const plan=report.plan,qualify=id=>qualifyInputOwner(model.placeId,id);
    async function prepare(){
      ready();if(prepared)return;if(preparing)return preparing;
      preparing=(async()=>{
        const loaded=[];for(const p of plan.projections){const buffers=await Promise.all([p.physical,p.render,p.mapping].map(ref=>loadProjection(ref,signal)));live();checkProjection(p,...buffers);loaded.push({p,buffers});}
        live();
        // No mutation until all resources/pins/mappings and abort checks pass.
        model.library={...model.library,geometries:{...model.library.geometries}};
        for(const {p,buffers:[physical,render]}of loaded){
          if(model.parts.length!==p.part.globalIndex||model.carriers.length!==p.owner.globalIndex)throw Error('Projection append revision changed');
          const owner={...structuredClone(p.owner),id:qualify(p.owner.id),parts:[p.part.globalIndex],supports:[],adjacency:[],supportEvidence:[],attachments:[],anchors:[]},part={...structuredClone(p.part),carrier:p.owner.globalIndex,carrierId:owner.id,material:owner.material,physical:true};
          model.library.geometries[part.physicalGeometry]=physical;model.library.geometries[part.geometry]=render;model.carriers.push(owner);model.carrierById.set(owner.id,owner);model.parts.push(part);model.partById.set(part.id,part);sources.registerProjectionCarrier(owner.id);
        }
        prepared=true;
      })();try{await preparing;}finally{preparing=null;}
    }
    function bindRegistry(registry){
      ready();if(!prepared)throw Error('Prepare map inputs before creating the world');if(binding)throw Error('Previous map input binding must be disposed before reset');
      const pins=[],originals=new Map(),bundles=new Map();let releaseProvider,producer,disposed=false;
      const dispose=()=>{if(disposed)return;disposed=true;producer?.dispose();if(producer)lastProducer=producer.diagnostics();releaseProvider?.();for(const p of pins)p.release();pins.length=0;originals.clear();bundles.clear();binding=null;};
      try{
        for(const p of plan.parts){const pin=registry.pinOriginal(p.id);pins.push(pin);if(pin.shape.triangles.length!==p.physicalTriangles)throw Error('Original source triangle count changed');originals.set(p.id,pin.shape);}
        releaseProvider=sources.useOriginalShapes(id=>{const shape=originals.get(id);if(!shape)throw Error('Out-of-cohort original source: '+id);return shape;});
        for(const o of plan.owners){const b=sources.sourcesForCarrier(o.id);bundles.set(o.id,b);for(const p of plan.parts.filter(p=>p.ownerId===o.id)){
          const ss=b.surfaces.filter(s=>s.nativePartId===p.id);if(ss.length!==p.surfacePlan.definitions||ss.reduce((n,s)=>n+s.triangles.length,0)!==p.surfacePlan.triangles)throw Error('Source blueprint derivation differs from admitted plan');
        }for(const s of b.surfaces){pins.push(registry.reserveSourceGeometry('input/'+s.id,s.triangles));if(s.solidTriangles&&s.solidTriangles!==s.triangles)pins.push(registry.reserveSourceGeometry('input-solid/'+s.id,s.solidTriangles));}}
        const endpoint=e=>{
          const part=model.partById.get(e.partId),ts=originals.get(e.partId).triangles,bp=e.bindingPlan,s=bundles.get(part.carrierId).surfaces.find(s=>s.id===part.carrierId+'/part/'+model.parts.indexOf(part)+'/'+bp.suffix),component=originalMaterialComponents(ts).find(c=>c.primitives.includes(e.primitive));
          if(component?.id!==e.component||segmentTriangle(e.point,e.point,ts[e.primitive])===null||!s)throw Error('Original endpoint component/primitive/surface differs from reviewed plan');
          const sourcePoint=bp.surfacePoint,box=bounds(s.triangles.flat()),lo=box.min.map((v,i)=>Math.floor(v/plan.grid.pitch[i]+EPS)),hi=box.max.map((v,i)=>v-box.min[i]<EPS?lo[i]:Math.ceil(v/plan.grid.pitch[i]-EPS)-1),cell=sourcePoint.map((v,i)=>Math.floor(v/plan.grid.pitch[i]+EPS));
          if(!sameInput(cell,bp.cell)||cell.some((v,i)=>v<lo[i]||v>hi[i])||!s.triangles.some(t=>segmentTriangle(sourcePoint,sourcePoint,t)!==null))throw Error('Own source projection/cell differs from reviewed plan');
          if(bp.channel==='surface'&&!sameInput(sourcePoint,e.point))throw Error('Surface endpoint requires its own source-face point');
          if(bp.channel==='solid'&&!s.triangles.some(t=>segmentTriangle(e.point,e.point,t)!==null))throw Error('Solid projection derivation is not ready for this source');
          const clip={min:cell.map((v,i)=>v*plan.grid.pitch[i]-EPS),max:cell.map((v,i)=>(v+1)*plan.grid.pitch[i]+EPS)};
          if(s.triangles.flatMap(t=>clipTriangle(t,clip)).reduce((n,t)=>n+triangleArea(t),0)<EPS)throw Error('Source endpoint has no positive thermal patch');
          return {partId:e.partId,point:[...e.point],primitives:[e.primitive],sourceSurfaceId:s.id,cell,nativeRecordId:null};
        };
        const support={parts:plan.parts.map(p=>({id:p.id,ownerId:p.ownerId})),bonds:plan.support.bonds.map(b=>({id:b.id,kind:b.kind,direction:b.direction,sourceSha256:b.proofRef.sha256,parent:endpoint(b.parent),child:endpoint(b.child)})),anchors:plan.support.anchors.map(({partId,elevation,component})=>({partId,elevation,component})),requirements:plan.support.requirements.map(g=>({id:g.id,ownerId:qualify(g.ownerId),portIds:g.portIds,upperBondId:g.upperBondId})),approvedMounts:[]};
